def is_valid_quantity(product_type, qty):
    if isinstance(qty, bool) or not isinstance(qty, int):
        return False
    if product_type == "bulk":
        return 100 <= qty <= 10000 and qty % 25 == 0
    if product_type == "unit":
        return 1 <= qty <= 99
    if product_type == "sample":
        return qty in (1, 3)
    return False
